<?php
namespace App\Infrastructure\Repositories\Eloquent;
use App\Domain\Contracts\Repositories\CartRepositoryInterface;use App\Domain\Models\Cart;use App\Domain\Models\CartItem;use App\Domain\Models\Product;use App\Domain\Models\ProductVariant;use InvalidArgumentException;
class CartRepository implements CartRepositoryInterface{private function load(Cart $c):Cart{return $c->load(['items.product','items.variant']);}public function getOrCreate(string $userId):Cart{return $this->load(Cart::firstOrCreate(['user_id'=>$userId]));}public function add(Cart $cart,string $productId,?string $variantId,int $quantity):Cart{$p=Product::whereKey($productId)->lockForUpdate()->firstOrFail();$v=$variantId?ProductVariant::where('product_id',$productId)->whereKey($variantId)->lockForUpdate()->firstOrFail():null;$available=$v?->stock_quantity??$p->stock;$item=CartItem::firstOrNew(['cart_id'=>$cart->id,'product_id'=>$productId,'product_variant_id'=>$variantId]);if(($item->quantity??0)+$quantity>$available)throw new InvalidArgumentException('الكمية المطلوبة تتجاوز المخزون المتاح.');$item->fill(['cart_id'=>$cart->id,'user_id'=>$cart->user_id,'product_id'=>$productId,'product_variant_id'=>$variantId,'quantity'=>($item->quantity??0)+$quantity])->save();return $this->load($cart);}public function update(Cart $cart,string $itemId,int $quantity):Cart{$item=$cart->items()->with(['product','variant'])->findOrFail($itemId);$available=$item->variant?->stock_quantity??$item->product->stock;if($quantity>$available)throw new InvalidArgumentException('الكمية المطلوبة تتجاوز المخزون المتاح.');$item->update(['quantity'=>$quantity]);return $this->load($cart);}public function remove(Cart $cart,string $itemId):Cart{$cart->items()->whereKey($itemId)->firstOrFail()->delete();return $this->load($cart);}public function clear(Cart $cart):void{$cart->items()->delete();}}
